    #define        TaskHeader_TaskState_STOPPED                             0x1
    #define        TaskHeader_TaskState_STOPPING                            0x2
    #define        TaskHeader_TaskState_RUNNING                             0x3
    #define        TaskHeader_TaskState_PAUSING                             0x5
    #define        TaskHeader_TaskState_PAUSED                              0x6

    #define     BA_TaskHeader_TaskType                         0x0003
    #define     B16TaskHeader_TaskType                         0x0002
    #define   LSb32TaskHeader_TaskType                            24
    #define   LSb16TaskHeader_TaskType                            8
    #define       bTaskHeader_TaskType                         4
    #define   MSK32TaskHeader_TaskType                            0x0F000000
    #define        TaskHeader_TaskType_Invalid                              0x0
    #define        TaskHeader_TaskType_BdDmxFilter                          0x1
    #define        TaskHeader_TaskType_BdDrmFilter                          0x2
    #define        TaskHeader_TaskType_TsDmxFilter                          0x3
    #define        TaskHeader_TaskType_TsBypassFilter                       0x4

    #define     BA_TaskHeader_uSrcId                           0x0003
    #define     B16TaskHeader_uSrcId                           0x0002
    #define   LSb32TaskHeader_uSrcId                              28
    #define   LSb16TaskHeader_uSrcId                              12
    #define       bTaskHeader_uSrcId                           4
    #define   MSK32TaskHeader_uSrcId                              0xF0000000
