    ///////////////////////////////////////////////////////////
    #define   GET32TaskHeader_pFunc(r32)                       _BFGET_(r32,15, 0)
    #define   SET32TaskHeader_pFunc(r32,v)                     _BFSET_(r32,15, 0,v)
    #define   GET16TaskHeader_pFunc(r16)                       _BFGET_(r16,15, 0)
    #define   SET16TaskHeader_pFunc(r16,v)                     _BFSET_(r16,15, 0,v)

    #define   GET32TaskHeader_TaskState(r32)                   _BFGET_(r32,23,16)
    #define   SET32TaskHeader_TaskState(r32,v)                 _BFSET_(r32,23,16,v)
    #define   GET16TaskHeader_TaskState(r16)                   _BFGET_(r16, 7, 0)
    #define   SET16TaskHeader_TaskState(r16,v)                 _BFSET_(r16, 7, 0,v)

    #define   GET32TaskHeader_TaskType(r32)                    _BFGET_(r32,27,24)
    #define   SET32TaskHeader_TaskType(r32,v)                  _BFSET_(r32,27,24,v)
    #define   GET16TaskHeader_TaskType(r16)                    _BFGET_(r16,11, 8)
    #define   SET16TaskHeader_TaskType(r16,v)                  _BFSET_(r16,11, 8,v)

    #define   GET32TaskHeader_uSrcId(r32)                      _BFGET_(r32,31,28)
    #define   SET32TaskHeader_uSrcId(r32,v)                    _BFSET_(r32,31,28,v)
    #define   GET16TaskHeader_uSrcId(r16)                      _BFGET_(r16,15,12)
    #define   SET16TaskHeader_uSrcId(r16,v)                    _BFSET_(r16,15,12,v)

            UNSG32 u_pFunc                                     : 16;
            UNSG32 u_TaskState                                 :  8;
