    #define     B16DSStreamOutEx_PAD_PrePushedDataCnt          0x001C
    #define   LSb32DSStreamOutEx_PAD_PrePushedDataCnt             0
    #define   LSb16DSStreamOutEx_PAD_PrePushedDataCnt             0
    #define       bDSStreamOutEx_PAD_PrePushedDataCnt          16
    #define   MSK32DSStreamOutEx_PAD_PrePushedDataCnt             0x0000FFFF

    #define     BA_DSStreamOutEx_PAD_Padding                   0x001E
    #define     B16DSStreamOutEx_PAD_Padding                   0x001E
    #define   LSb32DSStreamOutEx_PAD_Padding                      16
    #define   LSb16DSStreamOutEx_PAD_Padding                      0
    #define       bDSStreamOutEx_PAD_Padding                   16
    #define   MSK32DSStreamOutEx_PAD_Padding                      0xFFFF0000
