//////
/// 
/// $INTERFACE AACSDecFilter           biu              (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000 HDR                  (P)
///     # 0x00000 TskHdr               
///               $TaskHeader          TskHdr            REG          
///                                    ###
///                                    * Common task header
///                                    * AACS Decryption Filter decrypt m2ts files that are protected by AACS.
///                                    ###
///     @ 0x00004 FLAG                 (P)
///               %unsigned 1  isBypass                  0x0
///               %unsigned 1  isEncrypted               0x0
///               %unsigned 1  isBeOn                    0x0
///               %unsigned 3  CryptoFifoID              0x0
///               %%        26         # Stuffing bits...
///     @ 0x00008 IO                   (P)
///               %unsigned 16 pStrmInBuf                0x0
///                                    ###
///                                    * Input stream buffer pointer.
///                                    ###
///               %unsigned 16 pStrmOutBuf               0x0
///                                    ###
///                                    * Output stream buffer pointer.
///                                    ###
///     @ 0x0000C                      (P)
///               %unsigned 16 pLocalData                0x0
///                                    ###
///                                    * Internal local data memory address.
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00010                      (P)
///               %unsigned 16 packStartOffset           0x0
///                                    ###
///                                    * Offset within the data pack.
///                                    ###
///               %unsigned 16 packSizeToRd              0x0
///                                    ###
///                                    * AACS encryption pack size.
///                                    ###
///     @ 0x00014                      (P)
///               %unsigned 16 beBlockCnt                0x0
///                                    ###
///                                    * Current bus encryption unit offset against AACS encryption data pack.
///                                    ###
///               %unsigned 16 bePackSizeToRd            0x0
///                                    ###
///                                    * Bus encryption packet size.
///                                    ###
///     @ 0x00018 CTR                  (P)
///               %unsigned 32 DataCnt                   0x0
///                                    ###
///                                    * Data counter
///                                    ###
///     @ 0x0001C KEY                  (P)
///               %unsigned 16 pTitleKey                 0x0
///                                    ###
///                                    * Title key pointer
///                                    ###
///               %unsigned 16 pBusKey                   0x0
///                                    ###
///                                    * Bus key pointer
///                                    ###
///     @ 0x00020                      (P)
///     # 0x00020 pbBlockKey           
///               $UINT128             pbBlockKey        REG          
///                                    ###
///                                    * Block key
///                                    ###
///     @ 0x00030 IV                   (P)
///     # 0x00030 pbAacsIV             
///               $UINT128             pbAacsIV          REG          
///                                    ###
///                                    * Running IV within AACS encryption pack.
///                                    ###
///     @ 0x00040                      (P)
///     # 0x00040 pbBeIV               
///               $UINT128             pbBeIV            REG          
///                                    ###
///                                    * Running IV within Bus encryption pack.
///                                    ###
///     @ 0x00050                      (P)
///     # 0x00050 pbAacsConstIV        
///               $UINT128             pbAacsConstIV     REG          
///                                    ###
///                                    * Constant AACS encryption IV.
///                                    ###
///     @ 0x00060                      (P)
///     # 0x00060 pbBeConstIV          
///               $UINT128             pbBeConstIV       REG          
///                                    ###
///                                    * Constant Bus encryption IV.
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:     112B, bits:     854b, padding:     0B
////////////////////////////////////////////////////////////
