//////
/// 
/// $INTERFACE IndexContext            biu              (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000                      (P)
///     # 0x00000 contex               
///               $UINT32              contex            REG          
///                                    ###
///                                    * Value of 4 bytes context
///                                    ###
///     @ 0x00004                      (P)
///               %unsigned 32 sync_word                 
///                                    ###
///                                    * Value of the sync word
///                                    * Only valid when use_specified_sync_word in TspSwdCmd is one. Valid length of this field is defined by sync_word_length in TspSwdCmd. SWD only use this field for matching, it does not change the value of this field
///                                    ###
///     @ 0x00008                      (P)
///               %unsigned 3  IndexState                0x0
///                                    ###
///                                    * Intermediate processing state of indexing.
///                                    ###
///                                    : Normal                    0x0
///                                    : In_Middle_Of_Hdr          0x3
///                                    : In_Middle_Of_Hdr_To_Normal     0x4
///                                                 ###
///                                                 * Intentionally assign In_Middle_Of_XX to the last two values, so we could reduce some CMPx code while indexing
///                                                 ###
///               %unsigned 1  LastPktOutputted          0x0
///               %unsigned 2  OutputThisEs              0x0
///                                    : StopOutput                0x0
///                                    : Output                    0x1
///                                    : StoppingOutput            0x2
///               %unsigned 1  IsESOutput                0x0
///                                    : ArmRequested              0x1
///                                    : FigoDone                  0x0
///               %unsigned 2  uSyncSizeToGet            0x0
///                                    ###
///                                    * If partial sync data is in the current packet, it stands for the size of header in last packet
///                                    ###
///               %unsigned 5  uHdrSizeToGet             0x0
///                                    ###
///                                    * If the ES header data in current packet in not enough, update the remaining data size to get.
///                                    ###
///               %unsigned 2  uVideoEncType             0x0
///                                    : MPEG2                     0x0
///                                    : MPEG4                     0x1
///                                    : H264                      0x2
///                                    : VC1                       0x3
///               %unsigned 16 IndexBuf                  0x0
///     @ 0x0000C Seq                  (P)
///               %unsigned 16 SequenceParam             0x0
///               %unsigned 16 Reserved_1                0x0
///     @ 0x00010                      (P)
///               %unsigned 32 RecentPtsHigh             0x0
///     @ 0x00014                      (P)
///               %unsigned 32 RecentPtsLow              0x0
///     @ 0x00018                      (P)
///               %unsigned 32 RecentPtsPktCnt           0x0
///     @ 0x0001C                      (P)
///               %unsigned 32 PktWhereHdrNotEnough      0x0
///     @ 0x00020                      (P)
///               %unsigned 32 EsLastPktNum              0x0
///     @ 0x00024 PartialHdr           (P)
///               %unsigned 32 pHdrData_0i               
///     # 0x00028 PartialHdr1          
///               %unsigned 32 pHdrData_1i               
///     # 0x0002C PartialHdr2          
///               %unsigned 32 pHdrData_2i               
///     # 0x00030 PartialHdr3          
///               %unsigned 32 pHdrData_3i               
///     # 0x00034 PartialHdr4          
///               %unsigned 32 pHdrData_4i               
///     # 0x00038 PartialHdr5          
///               %unsigned 32 pHdrData_5i               
///     # 0x0003C PartialHdr6          
///               %unsigned 32 pHdrData_6i               
///     # 0x00040 PartialHdr7          
///               %unsigned 32 pHdrData_7i               
///     @ 0x00044                      (P)
///               %unsigned 32 EncryptionPktCnt          0x0
///                                    ###
///                                    * Indicate how many packets of this PID are encrypted before this pkt.
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:      72B, bits:     576b, padding:     0B
////////////////////////////////////////////////////////////
