/// $INTERFACE TsDmxFilter             biu              (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000                      (P)
///     # 0x00000 TskHdr               
///               $TaskHeader          TskHdr            REG          
///                                    ###
///                                    * Common task header
///                                    ###
///     @ 0x00004 TB                   (P)
///     # 0x00004 TBCtx                
///               $TimeBaseMon         TBCtx             REG          
///                                    ###
///                                    * Time base monitor context
///                                    ###
///     @ 0x00018 PID                  (P)
///               %unsigned 16 pgPidCtxTbl               0x0
///                                    ###
///                                    * Address of the global PID context table.
///                                    * LOCAL
///                                    ###
///               %unsigned 16 pLocalData                0x0
///                                    ###
///                                    * Address of the local data area for filter internal temporary use.
///                                    ###
///     @ 0x0001C CONST                (P)
///               %unsigned 16 pConstTbl                 0x0
///                                    ###
///                                    * Address of constant data area. That area is used to store constant table that used for video decoder padding data patterns.
///                                    * EVT
///                                    ###
///               %unsigned 16 pSrcEvtBuf                0x0
///                                    ###
///                                    * Destination buffer pointer for source level event output.
///                                    ###
///     @ 0x00020 CNT                  (P)
///               %unsigned 32 InDataCnt                 0x0
///                                    ###
///                                    * Input data counter, used to match input control tag when the input is from DDR.
///                                    ###
///     @ 0x00024 UNIT                 (P)
///               %unsigned 8  PktSize                   0xBC
///                                    ###
///                                    * TS packet size of the input stream.
///                                    ###
///               %unsigned 4  PktNum                    0x4
///                                    ###
///                                    * The number of TS packet to process each time.
///                                    ###
///               %unsigned 2  IsStreamStopping          0x0
///                                    ###
///                                    * 00: do not need to stop any psi or pes stream output
///                                    * 01: stop one of the pes output buffer
///                                    * 10: stop one of the psi output buffer
///                                    * 11: stop one of the ts record buffer
///                                    ###
///                                    : Stop_None                 0x0
///                                    : Stop_PES                  0x1
///                                    : Stop_PSI                  0x2
///                                    : Stop_TS_REC               0x3
///               %unsigned 1  IsDiscardMode             0x0
///               %unsigned 1  IsSuperPkt                0x0
///               %unsigned 8  CtxIdxOfStoppingStream    0x0
///                                    ###
///                                    * in stop PES and TS output buffer case, the CTX Index is the index in global PID ctx table
///                                    * in stop PSI case, the CTX index is the index in global PSI ctx table
///                                    * Dmx manager should fill this field before it sets IsStreamStopping to a nonzero number
///                                    ###
///               %unsigned 2  CryptoEngineAsyncFifo     0x0
///               %unsigned 2  CryptoEngineSyncFifo      0x1
///               %unsigned 1  NeedSrcEventOut           0x0
///               %unsigned 3  Reserved_1                0x0
///     @ 0x00028 INPUT                (P)
///               %unsigned 16 pInputBuf                 0x0
///                                    ###
///                                    * The address of the input buffer data structure.
///                                    ###
///               %unsigned 16 pgPartPesHdrTbl           0x0
///                                    ###
///                                    * Address of the global partial pes header table
///                                    ###
///     @ 0x0002C SEC                  (P)
///               %unsigned 16 pgSecCtxTbl               0x0
///                                    ###
///                                    * Address of the global section filter context table.
///                                    ###
///               %unsigned 16 pgPartSecHdrTbl           0x0
///                                    ###
///                                    * Address of the global section filter partial section header context table.
///                                    ###
///     @ 0x00030 Output               (P)
///               %unsigned 32 MinBufSpace               0x0
///                                    ###
///                                    * The minimum buffer space in all the connected buffer.
///                                    * Recaculate it when it is smaller than a threshold.
///                                    ###
///     @ 0x00034 PIDList              (P)
///               %unsigned 16 ListEntry                 0x0
///                                    ###
///                                    * Address of the first PID ctx in the PID linked list. FIGO use this list to filter its PIDs.
///                                    * It's maintained by both DMX manager and FIGO. When manager adds the first PID ctx to this list, this filed should be updated. When manager asks FIGO to remove the first list member, FIGO is responsible for updating this filed.
///                                    * 0
///                                    ###
///               %unsigned 16 Reserved_2                0x0
///     @ 0x00038 ECNT                 (P)
///               %unsigned 16 ErrTieDataCnt             0x0
///                                    ###
///                                    * The number of TS packet with transport error indicator.
///                                    ###
///               %unsigned 16 ErrAdfDataCnt             0x0
///                                    ###
///                                    * The number of TS packet with incorrect adaptation field length.
///                                    ###
///     @ 0x0003C TSIDUMP              (P)
///               %unsigned 16 NoOutputSpaceCnt          0x0
///                                    ###
///                                    * The number of no output space when dump TS packet.
///                                    ###
///               %unsigned 16 OutputBuf                 0x0
///                                    ###
///                                    * The address of the tsi dump output buffer data structure.
///                                    ###
///     @ 0x00040 TSIDUMP2             (P)
///               %unsigned 1  Enable                    0x0
///                                    ###
///                                    * 1: enable tsi dump;
///                                    * 0: disable tsi dump.
///                                    ###
///               %unsigned 1  ClrTSDumpEnable           0x0
///                                    ###
///                                    * 1: enable tsi clear TS dump;
///                                    * 0: enable tsi not decrypted/clear TS dump.
///                                    ###
///               %unsigned 14 Reserved_3                0x0
///               %unsigned 16 TsiDumpTmpBuf             0x0
///     @ 0x00044                      (P)
///     # 0x00044 DataToBeEncry        
///               $UINT32              DataToBeEncry     REG       [4]
///     @ 0x00054 TSECNT               (P)
///               %unsigned 16 ErrTSCnt                  0x0
///               %unsigned 16 Reserved_4                0x0
///     @ 0x00058 MUXTS                (P)
///               %unsigned 16 MuxHdrSz                  0x0
///               %unsigned 16 LtsidOfst                 0x0
///     @ 0x0005C SharedTSI            (P)
///               %unsigned 1  IsShareTsi                0x0
///                                    ###
///                                    * If share the TSI with other dmx instance
///                                    ###
///               %unsigned 1  IsTsiFirstInst            0x0
///                                    ###
///                                    * If the first dmx instance of this TSI input
///                                    ###
///               %unsigned 1  IsTsiLastInst             0x0
///                                    ###
///                                    * If the last dmx instance of this TSI input
///                                    ###
///               %unsigned 1  Reserved_5                0x0
///               %unsigned 12 PeekDataSize              0x0
///                                    ###
///                                    * The peeked data size for current tasks loop
///                                    ###
///               %unsigned 16 TsiFirstInst              0x0
///                                    ###
///                                    * The first dmx instance with the TSI
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:      96B, bits:     752b, padding:     0B
////////////////////////////////////////////////////////////
